ALTER TABLE "ingestion_batches" DROP CONSTRAINT "ingestion_batches_nonnegative_counts";--> statement-breakpoint
ALTER TABLE "ingestion_batches" DROP CONSTRAINT "ingestion_batches_request_digest_length";--> statement-breakpoint
ALTER TABLE "ingestion_endpoints" DROP CONSTRAINT "ingestion_endpoints_token_hash_length";--> statement-breakpoint
ALTER TABLE "ingestion_batches" ADD CONSTRAINT "ingestion_batches_payload_shape" CHECK (cardinality("ingestion_batches"."fields") between 1 and 100 and length("ingestion_batches"."idempotency_key") between 8 and 200);--> statement-breakpoint
ALTER TABLE "ingestion_batches" ADD CONSTRAINT "ingestion_batches_nonnegative_counts" CHECK ("ingestion_batches"."record_count" between 1 and 1000 and "ingestion_batches"."processed_record_count" between 0 and "ingestion_batches"."record_count" and "ingestion_batches"."created_row_count" >= 0 and "ingestion_batches"."updated_row_count" >= 0 and "ingestion_batches"."created_row_count" + "ingestion_batches"."updated_row_count" <= "ingestion_batches"."processed_record_count" and "ingestion_batches"."attempt" >= 0);--> statement-breakpoint
ALTER TABLE "ingestion_batches" ADD CONSTRAINT "ingestion_batches_request_digest_length" CHECK (length("ingestion_batches"."request_digest") = 64 and "ingestion_batches"."request_digest" ~ '^[0-9a-f]{64}$');--> statement-breakpoint
ALTER TABLE "ingestion_endpoints" ADD CONSTRAINT "ingestion_endpoints_text_lengths" CHECK (length("ingestion_endpoints"."name") between 1 and 120 and length("ingestion_endpoints"."record_key_field") between 1 and 120);--> statement-breakpoint
ALTER TABLE "ingestion_endpoints" ADD CONSTRAINT "ingestion_endpoints_token_hash_length" CHECK (length("ingestion_endpoints"."token_hash") = 64 and "ingestion_endpoints"."token_hash" ~ '^[0-9a-f]{64}$');--> statement-breakpoint
ALTER TABLE "ingestion_staged_records" ADD CONSTRAINT "ingestion_staged_records_values_shape" CHECK (jsonb_typeof("ingestion_staged_records"."values") = 'object' and pg_column_size("ingestion_staged_records"."values") <= 262144);